  &lt;img alt="콘솔 공동관 전경" src="https://game.donga.com/media/__sized__/images/2026/11/20/b1f5230880c14896-thumbnail-1920x1080-70.jpg"/&gt;
  &lt;figcaption&gt;
   콘솔 공동관 전경
  &lt;/figcaption&gt;
 &lt;/figure&gt;
 &lt;figure&gt;
  &lt;img alt="콘솔 공동관 전경" src="https://game.donga.com/media/__sized__/images/2026/11/20/acbf427210ab488e-thumbnail-1920x1080-70.jpg"/&gt;
  &lt;figcaption&gt;
   콘솔 공동관 전경
  &lt;/figcaption&gt;
 &lt;/figure&gt;
 &lt;figure&gt;
  &lt;img alt="지스타 콘솔 공동관 전경" src="https://game.donga.com/media/__sized__/images/2026/11/20/857f013f66754451-thumbnail-1920x1080-70.jpg"/&gt;
  &lt;figcaption&gt;
   지스타 콘솔 공동관 전경
